prompt:
请只写一个文件 mc_gate_ocn.cpp（C++20，全局 main）。

【硬性约束】
1. 允许 include： "mc_gate_dgp.h" "mc_gate_baselines.h" "mc_gate_adapter.h" "mc_gate_onc.h"
   标准头：<cstdint> <cstddef> <cstdio> <vector> <cmath>
2. 不要重新定义任何已存在的函数。main 第一行 `using namespace mc_gate;`。
3. 构建带 -Werror，零警告。只打印规定的行。

【已有接口（逐字）】
  ReturnMatrix generate(Family, Composition, int T, int N, double rho, double S, std::uint64_t seed);
  std::vector<uint32_t> assignment;  struct OncResult {
      OncStatus status;  // enum class OncStatus { OK, INVALID_INPUT, NO_VALID_PARTITION };
      ... };
  OncResult onc_partition(const std::vector<double>& corr, std::uint32_t asset_count, const OncSpec& spec);
  struct OncSpec { uint32_t min_clusters=2, max_clusters=4, min_cluster_size=2, max_iterations=100,
                   repeats=4; double distance_tolerance=1e-12; std::vector<uint64_t> seeds={17,29,43,71}; };
  WindowStats make_window_stats(const ResearchWindow&, bool abstain=false);
  Decision decide_from_stats(const WindowStats&, const RuleConfig&);
  struct RuleConfig { GateMode mode; double q; double alpha; };
  struct ResearchWindow { std::span<const double> returns; std::size_t trials, observations; std::uint64_t returns_sha256; };

【要写的辅助函数（照抄）】
  static std::uint64_t sm(std::uint64_t x){x+=0x9E3779B97F4A7C15ULL;x=(x^(x>>30))*0xBF58476D1CE4E5B9ULL;
      x=(x^(x>>27))*0x94D049BB133111EBULL;return x^(x>>31);}

  static std::vector<double> corr_of(const ReturnMatrix& m) {   // 返回 T x T 行主序
      const int T=m.T, N=m.N;
      std::vector<double> mu(T,0.0), sd(T,0.0);
      for(int i=0;i<T;i++){ double s=0; for(int t=0;t<N;t++) s+=m.at(i,t); mu[(std::size_t)i]=s/N;
          double v=0; for(int t=0;t<N;t++){ double d=m.at(i,t)-mu[(std::size_t)i]; v+=d*d; }
          sd[(std::size_t)i]=std::sqrt(v/(N-1)); }
      std::vector<double> c((std::size_t)T*(std::size_t)T,0.0);
      for(int a=0;a<T;a++){ c[(std::size_t)a*T+a]=1.0;
          for(int b=a+1;b<T;b++){ double s=0;
              for(int t=0;t<N;t++) s+=(m.at(a,t)-mu[(std::size_t)a])*(m.at(b,t)-mu[(std::size_t)b]);
              double den=(N-1)*sd[(std::size_t)a]*sd[(std::size_t)b];
              double r= den>0.0 ? s/den : 0.0;
              if(r>1.0)r=1.0; if(r<-1.0)r=-1.0;
              c[(std::size_t)a*T+b]=r; c[(std::size_t)b*T+a]=r; } }
      return c;
  }

【main 要做的事】
常量：N=126, REPS=400, Q=0.05, OncSpec spec(默认构造)。
对 comp ∈ {Composition::Null（S=0）, Composition::OneGood（S=1.8）}，
对 T ∈ {4,20,100}，对 rho ∈ {0.0,0.3,0.7}：
    int abstain=0, sel_all=0, sel_cond=0, ok=0;
    for rep in 0..REPS-1:
        ReturnMatrix m = generate(Family::T5, comp, T, N, rho, S,
                                  sm(9137ULL ^ ((std::uint64_t)T<<36) ^ ((std::uint64_t)(rho*10)<<20) ^ (std::uint64_t)rep));
        std::vector<double> corr = corr_of(m);
        OncResult oc = onc_partition(corr, (std::uint32_t)T, spec);
        if (oc.status != OncStatus::OK) { ++abstain; continue; }
        ++ok;
        // 构造 ResearchWindow（trial-major）
        std::vector<double> flat((std::size_t)T*(std::size_t)N);
        for(int i=0;i<T;i++) for(int t=0;t<N;t++) flat[(std::size_t)i*N+t]=m.at(i,t);
        ResearchWindow w{ std::span<const double>(flat.data(), flat.size()),
                          (std::size_t)T, (std::size_t)N, 0 };
        Decision d = decide_from_stats(make_window_stats(w,false), RuleConfig{ GateMode::Full, Q, Q });
        if (d.selected) { ++sel_all; ++sel_cond; }
    // 注意：sel_all 只在 OCN 成功时才可能 +1，所以 sel_all/REPS 就是"含弃权的总选中率"；
    //       另需一份"若 OCN 成功才计数"的分子：用 sel_cond / ok。
    打印一行（字段用 %d %d %.1f %.4f %.4f %.4f）：
    OCNROW <T> <是否 one_good:0/1> <rho*10 取整> <abstain/REPS> <sel_all/REPS> <sel_cond/ok，ok=0 时打 0>
全部跑完后打印 OCN_DONE，return 0。

【输出纪律】
  OCNROW 共 2（comp）× 3（T）× 3（rho）= 18 行 + 1 行 OCN_DONE。
  字段顺序：OCNROW T comp rho10 abstain_rate sel_all_rate sel_cond_rate
